package com.railflow.yardops.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="yards") public class Yard { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(unique=true) private String code; private String name; private String city; private Integer trackCapacity; private Integer occupiedTracks; protected Yard(){} public Yard(String code,String name,String city,Integer trackCapacity,Integer occupiedTracks){this.code=code;this.name=name;this.city=city;this.trackCapacity=trackCapacity;this.occupiedTracks=occupiedTracks;} public UUID getId(){return id;} public String getCode(){return code;} public String getName(){return name;} public String getCity(){return city;} public Integer getTrackCapacity(){return trackCapacity;} public Integer getOccupiedTracks(){return occupiedTracks;} public double utilization(){return trackCapacity==0?0:(occupiedTracks*100.0/trackCapacity);} }